/*
 * Bionic's symbol versions for the libc entry points this library supplies. OH's loader matches a
 * versioned import against a versioned library by the version's hash, so an export must carry the
 * version Bionic gives it: Messenger's libcore.so asks for __system_property_read_callback@LIBC_O
 * and could not bind to it under LIBC. Unversioned imports match any default version.
 */
LIBC_N {
    global:
        __pwrite64_chk;
};

LIBC_O {
    global:
        __system_property_read_callback;
} LIBC_N;

LIBC_P {
    global:
        sigaction64;
        sigaddset64;
        sigdelset64;
        sigemptyset64;
        sigfillset64;
        sigismember64;
        sigprocmask64;
        pthread_sigmask64;
} LIBC_O;

LIBC_Q {
    global:
        android_fdsan_close_with_tag;
        android_fdsan_create_owner_tag;
        android_fdsan_exchange_owner_tag;
        android_fdsan_get_error_level;
        android_fdsan_get_owner_tag;
        android_fdsan_get_tag_type;
        android_fdsan_get_tag_value;
        android_fdsan_set_error_level;
        android_get_device_api_level;
} LIBC_P;

LIBC_R {
    global:
        android_fdsan_set_error_level_from_property;
} LIBC_Q;

/*
 * libmozglue.so's version, for the forwarders that give Firefox's libraries libmozglue's own
 * allocator, environment and abort (see westlake_resolve_mozglue): defined only as non-default
 * versions, so only an import that names this version binds to them.
 */
libmozglue.so {
};

/*
 * libnativewindow.so's version, for the buffer and dataspace calls its importers ask for by
 * name@LIBNATIVEWINDOW: Maps' and YouTube's libgoogle3.so, TensorFlow Lite's GPU delegate, two
 * games' frame-rate layer. A versioned import does not bind to a definition under another version,
 * and the catch-all below would give these LIBC. Unversioned importers (Instagram's
 * libgraphics-core.so) match this as the default version, so they bind as before.
 */
LIBNATIVEWINDOW {
    global:
        AHardwareBuffer_acquire;
        AHardwareBuffer_allocate;
        AHardwareBuffer_describe;
        AHardwareBuffer_lock;
        AHardwareBuffer_release;
        AHardwareBuffer_unlock;
        ANativeWindow_getBuffersDataSpace;
        ANativeWindow_setBuffersDataSpace;
};

/*
 * libbinder_ndk.so's version (API 29), for the calls the runtime's libbinder_ndk.so does not define:
 * Edge's libchrome.so imports AIBinder_getCallingPid@LIBBINDER_NDK and did not load without it. The
 * runtime's library has no versions, so it still answers the other LIBBINDER_NDK imports.
 */
LIBBINDER_NDK {
    global:
        AIBinder_getCallingPid;
        AIBinder_getCallingUid;
};

LIBC {
    global:
        *;
} LIBC_Q;
